#include <stdio.h>
#include <stdlib.h>
#include <string.h>

void decode(char *str, char *key, char *val) {
    int i, j;
    for (i = 0, j = 0; str[i]; i++) {
        if (str[i] == '+') {
            val[j++] = ' ';
        } else if (str[i] == '%') {
            if (i + 2 < strlen(str)) {
                val[j++] = (str[i + 1] - '0') * 16 + str[i + 2] - '0';
                i += 2;
            }
        } else {
            val[j++] = str[i];
        }
    }
    val[j] = '\0';
}

int main() {
    char line[1024], key[1024], val[1024];
    while (fgets(line, sizeof(line), stdin)) {
        char *p = line;
        while (*p) {
            if (*p == '=') {
                *p = '\0';
                decode(p + 1, key, val);
                printf("%s=%s\n", key, val);
                p += strlen(p + 1) + 1;
            } else if (*p == '&') {
                *p = '\0';
                p++;
            } else {
                strcpy(key, p);
                p += strlen(p);
            }
        }
    }
    return 0;
}
